-- The default roles are a preselection a venue may change (Martin 11-09, ticket #366). Generated by
-- drizzle-kit, with this note. One nullable column says whether the venue has edited a default
-- role: null (every row there is today) means "as Restro ships it", so the role keeps reading
-- core's table and a permission shipped later still reaches it — no backfill, and nobody's rights
-- move when this lands. Once the venue ticks one, the column holds the permission keys the code
-- knew at that moment and the row's own `permissions` is what the role grants; a key added later
-- is then new to the role and arrives unticked. Only Staff and Manager carry it: the Owner role is
-- fixed, so that an owner can never take `settings.roles` off their own role.

ALTER TABLE "restro"."venue_roles" ADD COLUMN "known_permissions" jsonb;--> statement-breakpoint
ALTER TABLE "restro"."venue_roles" ADD CONSTRAINT "venue_roles_known_permissions_array" CHECK ("restro"."venue_roles"."known_permissions" is null or jsonb_typeof("restro"."venue_roles"."known_permissions") = 'array');--> statement-breakpoint
ALTER TABLE "restro"."venue_roles" ADD CONSTRAINT "venue_roles_known_permissions_default_only" CHECK ("restro"."venue_roles"."known_permissions" is null or "restro"."venue_roles"."default_kind" in ('staff', 'manager'));